}

function createRelationshipGuide(
  points: number
) {
  const statusRule = `
【関係性の共通ルール】

relationshipPoints は親しさの目安であって、
「付き合っている」という事実そのものではありません。

恋人・交際中・前から好きだった等の関係事実は、
