+  await processRelationshipTurn(db.worker() as any, "owner", breakup.requestId, async () => [], async () => true);
+  assert.deepEqual(db.store(turn.requestId).eventRows.map(e => e.event_type), ["romantic_acceptance", "relationship_end"]);
